/* One concept or original-book task at a time. Answers are never rendered before submission. */
(()=>{
 'use strict';
 const instances=new WeakMap();
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const plain=v=>Array.isArray(v)?v.join('；'):String(v??'');
 const clamp=(v,n)=>Math.max(0,Math.min(Math.max(0,n-1),Number.isInteger(+v)?+v:0));
 const norm=v=>String(v??'').normalize('NFKC').trim().toLowerCase().replace(/[‘’]/g,"'").replace(/\s+/g,' ');
 const keyOf=(q,i)=>String(q.id??`item-${i+1}`);
 const auto=q=>q.autoGrade!==false&&(Boolean(q.options?.length)||q.autoGrade===true||q.answerMode==='exact');
 const multi=q=>Array.isArray(q.answer)&&Boolean(q.options?.length);
 const qs=m=>Array.isArray(m?.items)?m.items:[];
 function url(s){try{const u=new URL(s,location.href);return s&&['http:','https:'].includes(u.protocol)?s:''}catch{return ''}}
 const link=(s,t)=>url(s)?`<a class="ch-text-link" href="${esc(url(s))}" target="_blank" rel="noopener">${esc(t)} ↗</a>`:'';
 function matches(v,q){if(multi(q)){try{const a=JSON.parse(v);return Array.isArray(a)&&a.length===q.answer.length&&a.map(norm).sort().join('|')===q.answer.map(norm).sort().join('|')}catch{return false}}return [q.answer,...(q.alternatives||[])].some(a=>norm(a)===norm(v))}
 function answer(q){if(q.referenceAnswer)return plain(q.referenceAnswer);return (Array.isArray(q.answer)?q.answer:[q.answer]).map(a=>q.options?.find(o=>String(o.value)===String(a))?.label??plain(a)).join('；')}
 function hasAnswer(q,v){if(multi(q)){try{return Array.isArray(JSON.parse(v))&&JSON.parse(v).length>0}catch{return false}}return Boolean(v.trim())}
 function render(host,opts){
  if(!host||!opts?.lesson||!opts?.state)throw Error('StudyChapters.render requires host, lesson and state.');
  instances.get(host)?.destroy();
  const {lesson:l,course:c=null,state:s}=opts,rules=l.rules||[],missions=c?.missions||[],id=String(l.id),cid=String(c?.id??id),abort=new AbortController();
  for(const k of ['tasks','drafts','results','read'])if(!s[k]||typeof s[k]!=='object'||Array.isArray(s[k]))throw Error(`Missing state.${k}`);
  const positionKey=`chapter:${id}:position`,mk=m=>`book:${cid}:${m.id}`,dk=(m,k)=>`${mk(m)}:${k}`,read=i=>s.tasks[`learn:${id}:${i}`]===true,partial=m=>Boolean(qs(m).length&&(m.itemsPartial===true||c?.itemsPartial===true));
  const result=m=>s.results[mk(m)],checked=(m,q,i)=>result(m)?.checked?.[keyOf(q,i)];
  const incomplete=m=>Boolean(m.missingTasks?.length||qs(m).some(q=>q.blocked));
  const completed=m=>!incomplete(m)&&(qs(m).length?qs(m).every((q,i)=>checked(m,q,i)?.reviewed)&&(!partial(m)||result(m)?.groupAssessed===true):result(m)?.status==='complete');
  const paneCount=r=>r?.steps?.length||r?.breakdown?.length||r?.check?3:1;
  let view='overview',step=0,learnPane=0,mi=0,ii=0,destroyed=false,saved={};try{saved=JSON.parse(s.drafts[positionKey]||'{}')||{}}catch{}
  const notify=t=>opts.toast?.(t);
  function save(active=false){try{opts.save?.(active)?.catch?.(()=>notify('保存暂未成功，请保持页面打开后重试。'))}catch{notify('保存暂未成功，请保持页面打开后重试。')}}
  function award(k){if(s.tasks[k]===true)return;s.tasks[k]=true;opts.reward?.()}
  function persist(){saved={view,step,learnPane,missionIndex:mi,itemIndex:ii};s.drafts[positionKey]=JSON.stringify(saved);save()}
  function move(next,p={}){view=next;step=clamp(p.step??step,rules.length);learnPane=clamp(p.learnPane??0,paneCount(rules[step]));mi=clamp(p.missionIndex??mi,missions.length);ii=clamp(p.itemIndex??0,qs(missions[mi]).length);persist();draw();host.querySelector('#ch-view-title')?.focus({preventScroll:true});window.scrollTo?.({top:0,behavior:'instant'})}
  function fresh(m){const items=qs(m),available=items.filter(q=>!q.blocked),n=available.length+(partial(m)||!items.length?1:0),a=available.filter(auto).length;return {score:0,total:n,automaticScore:0,automaticTotal:a,selfScore:0,selfTotal:n-a,selfAssessed:false,grading:a===n?'objective':a?'mixed':'self',reviewNeed:false,submitted:false,status:'in-progress',checked:{},firstAttempts:{},pendingReviewIds:[],contentVersion:2,attempt:1}}
  function ensure(m){let r=result(m);if(!r||typeof r!=='object'){r=fresh(m);s.results[mk(m)]=r}r.checked??={};r.firstAttempts??={};r.pendingReviewIds??=[];return r}
  function aggregate(m,reward=true){
   const r=ensure(m),items=qs(m),available=items.filter(q=>!q.blocked),all=items.length>0&&items.every((q,i)=>q.blocked||checked(m,q,i)?.reviewed);
   r.total=available.length+(partial(m)||!items.length?1:0);r.automaticTotal=available.filter(auto).length;r.selfTotal=r.total-r.automaticTotal;
   r.automaticScore=items.filter((q,i)=>!q.blocked&&auto(q)&&checked(m,q,i)?.correct===true).length;
   r.selfScore=items.filter((q,i)=>!q.blocked&&!auto(q)&&checked(m,q,i)?.correct===true).length+(r.groupAssessed&&r.groupCorrect?1:0);r.score=r.automaticScore+r.selfScore;
   r.selfAssessed=Boolean(r.groupAssessed)||items.some((q,i)=>!q.blocked&&!auto(q)&&checked(m,q,i)?.reviewed);r.itemsSubmitted=all;
   r.reviewNeed=items.some((q,i)=>checked(m,q,i)?.reviewed&&checked(m,q,i)?.correct===false)||Boolean(r.groupAssessed&&!r.groupCorrect)||r.pendingReviewIds.length>0||Boolean(r.pendingGroupReview)||Boolean(r.manualReview);
   r.grading=r.automaticTotal===r.total?'objective':r.automaticTotal?'mixed':'self';r.availableComplete=all;
   const done=!incomplete(m)&&(items.length?all&&(!partial(m)||r.groupAssessed===true):Boolean(r.groupAssessed));r.submitted=done||Boolean(r.groupSubmitted);r.status=done?'complete':all&&incomplete(m)?'source-incomplete':r.groupSubmitted?'submitted':'in-progress';
   if(done&&reward){r.finishedAt=new Date().toISOString();award(mk(m))}return done;
  }
  // Group completion from the image-based edition does not complete newly transcribed items.
  let migrated=false;for(const m of missions){const r=result(m);if(!r||!(m.contentVersion===2||m.textComplete)||r.contentVersion===2)continue;r.legacySummary={score:r.score,total:r.total,status:r.status||'unknown'};r.contentVersion=2;if(r.reviewNeed&&!Object.values(r.checked||{}).some(v=>v.correct===false)&&!(r.groupAssessed&&!r.groupCorrect)&&!r.pendingReviewIds?.length&&!r.pendingGroupReview)r.manualReview=true;r.firstAttempts??={};for(const [key,old] of Object.entries(r.checked||{}))if(old.submitted&&!r.firstAttempts[key])r.firstAttempts[key]={kind:'legacy',correct:null};aggregate(m,false);migrated=true}if(migrated)save();
  function learn(){const n=rules.findIndex((_,i)=>!read(i));move('learn',{step:saved.view==='learn'&&rules[saved.step]&&!read(+saved.step)?+saved.step:n<0?0:n,learnPane:saved.view==='learn'?saved.learnPane:0})}
  function practice(){let n=['practice','group','result'].includes(saved.view)?clamp(saved.missionIndex,missions.length):missions.findIndex(m=>!completed(m));if(n<0)n=0;const m=missions[n];if(!m)return;const i=qs(m).findIndex((q,j)=>!checked(m,q,j)?.reviewed);move(i<0&&(completed(m)||result(m)?.availableComplete)?'result':qs(m).length?'practice':'group',{missionIndex:n,itemIndex:i<0?0:i})}
  function directory(mode){return `<details class="ch-directory"><summary>${mode==='learn'?'知识点目录':'练习目录'}</summary><div>${(mode==='learn'?rules:missions).map((x,i)=>`<button data-ch-action="${mode==='learn'?'learn-step':'mission'}" data-index="${i}"><span>${String(i+1).padStart(2,'0')}</span>${esc(x.title)}<small>${mode==='learn'?(read(i)?'已阅读':''):(completed(x)?'已完成':result(x)?.status==='source-incomplete'?'待补资料':'')}</small></button>`).join('')}</div></details>`}
  function header(){if(view==='overview')return `<div class="ch-topline"><button class="ch-back" data-ch-action="back">← 教材章节</button><span>拾阶 / ${esc(l.title)}</span></div><header class="ch-header"><p class="ch-kicker">TEXTBOOK LEARNING</p><h1 id="ch-view-title" tabindex="-1">${esc(l.title)}</h1><p>${esc(l.subtitle)}</p></header>`;const learning=view==='learn'||view==='learn-done';return `<div class="ch-focus-bar"><button class="ch-back" data-ch-action="overview">← 章节总览</button><span>${esc(l.title)} · ${learning?'学习':'练习'}</span>${directory(learning?'learn':'practice')}</div>`}
  function overview(){const learned=rules.filter((_,i)=>read(i)).length,done=missions.filter(completed).length,n=missions.reduce((sum,m)=>sum+qs(m).length,0),text=missions.length&&missions.every(m=>m.textComplete);return `<section class="ch-launch"><div class="ch-overview-meta"><span>学习 ${learned} / ${rules.length}</span>${missions.length?`<span>练习 ${done} / ${missions.length} 组</span>`:''}</div><h2>从一个小步骤开始。</h2><p>${missions.length?'先把知识点想明白，再用书上的题练习。也可以直接进入练习。':'本专题提供补充讲解，目前没有已核对的原书练习。'}</p><div class="ch-overview-actions"><button class="ch-entry" data-ch-action="learn-tab"><span class="ch-entry-icon">Aa</span><strong>${learned?'继续学习':'开始学习'}</strong><small>${rules.length} 个知识点 · 逐步理解</small><span aria-hidden="true">→</span></button>${missions.length?`<button class="ch-entry" data-ch-action="practice-tab"><span class="ch-entry-icon">✎</span><strong>${done?'继续练习':'开始练习'}</strong><small>${text?`${n} 项教材任务 · 一次一道`:`${missions.length} 组教材练习`}</small><span aria-hidden="true">→</span></button>`:''}</div>${missions.some(m=>result(m)?.reviewNeed)?'<button class="ch-text-link" data-ch-action="review">复习本章错题 →</button>':''}<p class="ch-progress-note">阅读与答题结果分开保存。开放题完成度包含你的对照自评。</p>${missions.some(incomplete)?`<p class="ch-progress-note">本章 ${missions.filter(incomplete).length} 组引用的附件未随教材提供。正文可照常练习，缺失部分会标为“待补资料”。</p>`:''}</section><details class="ch-source-details"><summary>教材来源与整理说明</summary><p>${esc(plain(c?.coverageNote||l.source))}</p>${link(c?.sourcePdf,'查看教材 PDF')}${link(c?.answerPdf,'查看配套答案 PDF')}</details>`}
  const ck=()=>`learn-check:${id}:${step}`;
  function understanding(r){if(!r.check)return '';const q=r.check,k=ck(),value=s.drafts[k]||'',res=s.results[k];return `<section class="ch-understanding"><span class="ch-mini-label">试着判断 · 理解检查（非教材原题）</span><h3>${esc(q.prompt)}</h3><fieldset class="ch-options" ${res?.submitted?'disabled':''}><legend class="ch-sr-only">选择理解检查答案</legend>${q.options.map(o=>`<label class="ch-option"><input type="radio" name="learn-check" data-ch-input="learn-check" value="${esc(o.value)}" ${value===o.value?'checked':''}><span>${esc(o.label)}</span></label>`).join('')}</fieldset>${res?.submitted?`<div class="ch-item-feedback ${res.score?'correct':'incorrect'}" role="status"><strong>${res.score?'✓ 判断正确':'再想清楚这一步'}</strong><p>${esc(!res.score&&q.wrongExplanation?q.wrongExplanation:q.explanation)}</p></div><button class="ch-text-link" data-ch-action="retry-check">再判断一次</button>`:`<button class="ch-secondary" data-ch-action="check-learning" ${!value?'disabled':''}>核对理解</button>`}</section>`}
  function learnView(){
    if(!rules.length)return '<p>本专题暂未提供知识点。</p>';
    const r=rules[step],n=paneCount(r),last=learnPane===n-1;
    const explain=`<p class="ch-explanation">${esc(r.explanation)}</p>${r.steps?.length?`<section class="ch-method"><h2>做题时，这样判断</h2><ol>${r.steps.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></section>`:''}`;
    const examples=`${r.example?`<section class="ch-rule-example"><span class="ch-mini-label">看一个例子</span><p>${esc(r.example)}</p>${r.breakdown?.length?`<dl class="ch-breakdown">${r.breakdown.map(p=>`<div><dt>${esc(p.text)}</dt><dd>${esc(p.note)}</dd></div>`).join('')}</dl>`:''}</section>`:''}${r.before||r.after?`<div class="ch-comparison">${r.before?`<section class="ch-before"><span>容易写成这样</span><p>${esc(r.before)}</p></section>`:''}${r.after?`<section class="ch-after"><span>可以这样修改</span><p>${esc(r.after)}</p></section>`:''}</div>`:''}`;
    const check=`${r.pitfall?`<p class="ch-pitfall"><strong>记住这一点：</strong>${esc(r.pitfall)}</p>`:''}${understanding(r)}`;
    const pending=last&&Boolean(r.check)&&!s.results[ck()]?.submitted;
    return `<article class="ch-panel ch-learn-card"><div class="ch-card-top"><span class="ch-kicker">知识点 ${step+1} / ${rules.length}</span><span class="ch-status">${read(step)?'已阅读 · 回顾中':'学习中'}</span></div><progress value="${step+1}" max="${rules.length}" aria-label="当前知识点位置"></progress><h1 id="ch-view-title" tabindex="-1">${esc(r.title)}</h1>${n>1?`<div class="ch-learning-phases" aria-label="当前知识点的三个小步骤">${['理解规则','拆解例句','试着判断'].map((label,i)=>`<span class="${i===learnPane?'active':''}" ${i===learnPane?'aria-current="step"':''}>${i+1} ${label}</span>`).join('')}</div>`:''}${n===1?explain+examples:learnPane===0?explain:learnPane===1?examples:check}<div class="ch-learn-footer"><button class="ch-secondary" data-ch-action="previous-step" ${step===0&&learnPane===0?'disabled':''}>← 上一步</button><button class="ch-primary" data-ch-action="learn-next" ${pending?'disabled':''}>${last?(step<rules.length-1?'下一知识点':'完成本次学习'):learnPane===0?'下一步：看例句':'下一步：试着判断'} →</button></div>${pending?'<p class="ch-progress-note">先试着回答一次，再查看讲解。答错也可以继续学习。</p>':''}<p class="ch-footnote">${esc(r.sourceLabel||'中文教学与讲解示例；正式原题请进入练习。')} · 阅读不会自动算作答题掌握。</p></article>`;
  }

  function learnedSummary(){return `<section class="ch-panel ch-completion"><span class="ch-result-symbol">✓</span><h1 id="ch-view-title" tabindex="-1">这一段学习，完成了。</h1><p>已阅读 ${rules.filter((_,i)=>read(i)).length} / ${rules.length} 个知识点。接下来用教材原题检验理解。</p><div class="ch-actions">${missions.length?'<button class="ch-primary" data-ch-action="practice-tab">开始教材练习 →</button>':''}<button class="ch-secondary" data-ch-action="overview">返回章节总览</button></div></section>`}
  function feedback(m,q,i){const v=checked(m,q,i);if(!v?.submitted)return '';const automatic=auto(q),good=v.correct===true,body=`<div class="ch-reference-answer"><span>${automatic?'本题答案':'参考作答'}</span><p>${esc(answer(q)||'本题允许不同表达，请按下列要求自查。')}</p></div><p>${esc(q.explanation||'结合题目要求，核对所学的句子结构。')}</p>${q.rubric?.length?`<ul class="ch-rubric">${q.rubric.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:''}`;return `<section class="ch-item-feedback ${v.reviewed?good?'correct':'incorrect':'pending'}" role="status"><strong>${automatic?(good?'✓ 回答正确':'这题需要再看一步'):v.reviewed?(good?'✓ 已自评符合要求':'已标记待复习'):'已提交，请对照参考检查'}</strong>${automatic&&good?`<details class="ch-correct-explanation"><summary>查看本题讲解</summary>${body}</details>`:body}${!automatic&&!v.reviewed?'<p class="ch-self-disclaimer">开放表达允许不同答案。这里提供参考与检查标准，系统没有自动判定正误。</p><div class="ch-actions"><button class="ch-primary" data-ch-action="self-item" data-choice="mastered">已对照，符合要求</button><button class="ch-secondary" data-ch-action="self-item" data-choice="review">还需复习</button></div>':''}</section>`}
  function itemView(m){const items=qs(m),q=items[ii];if(q.blocked)return `<article class="ch-panel ch-item-card"><span class="ch-kicker">教材第 ${ii+1} / ${items.length} 项</span><h1 id="ch-view-title" tabindex="-1">${esc(q.prompt)}</h1><p class="ch-missing-material">${esc(q.missingReason)}</p><p>这项需要的原文没有包含在当前资料中，暂不能作答，不计为已完成。</p><button class="ch-primary" data-ch-action="next-item">继续其他题目 →</button></article>`;const k=keyOf(q,ii),v=checked(m,q,ii),value=s.drafts[dk(m,k)]||'',locked=Boolean(v?.submitted);let chosen=[];if(multi(q))try{chosen=JSON.parse(value)}catch{}return `<article class="ch-panel ch-item-card"><div class="ch-card-top"><span class="ch-kicker">第 ${ii+1} / ${items.length} 题</span><span class="ch-status">${auto(q)?'自动核对':'对照自评'}</span></div><progress value="${ii+1}" max="${items.length}" aria-label="当前题目位置"></progress><p class="ch-question-group">${esc(m.title)}${q.sourceNumber?` · 原题 ${esc(q.sourceNumber)}`:''}</p>${m.instructions?`<p class="ch-task-instruction ch-group-instruction"><strong>本组要求：</strong>${esc(m.instructions)}</p>`:''}${missingNote(m)}${q.instruction?`<p class="ch-task-instruction">${esc(q.instruction)}</p>`:''}<h1 class="ch-question-prompt" id="ch-view-title" tabindex="-1">${esc(q.prompt)}</h1>${q.passage?`<section class="ch-passage" aria-label="本题阅读材料">${esc(plain(q.passage))}</section>`:''}${q.options?.length?`<fieldset class="ch-options" ${locked?'disabled':''}><legend class="ch-sr-only">${multi(q)?'选择所有符合的答案':'选择一个答案'}</legend>${q.options.map((o,i)=>{const selected=multi(q)?chosen.map(String).includes(String(o.value)):value===String(o.value);return `<label class="ch-option ${selected?'selected':''}"><input type="${multi(q)?'checkbox':'radio'}" name="chapter-option" data-ch-input="option" value="${esc(o.value)}" ${selected?'checked':''}><span class="ch-option-letter">${String.fromCharCode(65+i)}</span><span>${esc(o.label)}</span></label>`}).join('')}</fieldset>`:`<label class="ch-answer-label" for="ch-item-response">你的作答</label><textarea id="ch-item-response" data-ch-input="item" rows="${q.passage?8:4}" placeholder="在这里写下你的答案…" ${locked?'readonly':''} spellcheck="false">${esc(value)}</textarea>`}${feedback(m,q,ii)}<div class="ch-item-footer">${!locked?`<button class="ch-primary" data-ch-action="check-item" ${!hasAnswer(q,value)?'disabled':''}>${auto(q)?'提交答案':'提交，查看参考'} →</button>`:`${v.reviewed?`<button class="ch-primary" data-ch-action="next-item">${ii<items.length-1?'下一题':'完成本组'} →</button>`:''}<button class="ch-text-link" data-ch-action="edit-item">重新作答</button>`}<button class="ch-text-link" data-ch-action="previous-item" ${ii===0?'disabled':''}>上一题</button></div><details class="ch-item-source"><summary>原题出处 · 草稿自动保存</summary><p>${esc(q.sourceLabel||'教材原题')}</p></details></article>`}
  function pages(m,answer=false){return `<details class="ch-legacy-source"><summary>${answer?'查看配套答案原页':'查看教材原页（可能含原有填答）'}</summary>${((answer?m.answerPages:m.sourcePages)||[]).map(p=>`<figure><a href="${esc(url(p.src))}" target="_blank" rel="noopener"><img src="${esc(url(p.src))}" alt="${esc(p.label)}" loading="lazy"></a><figcaption>${esc(p.label)}</figcaption></figure>`).join('')}${link(answer?c?.answerPdf:c?.sourcePdf,answer?'答案 PDF':'教材 PDF')}</details>`}
  function groupView(m){const r=result(m),value=s.drafts[dk(m,'response')]||'';return `<article class="ch-panel ch-open-response"><span class="ch-kicker">教材原题 · ${mi+1} / ${missions.length} 组</span><h1 id="ch-view-title" tabindex="-1">${esc(m.title)}</h1><p>${esc(m.instructions||'按原书题号填写作答，再对照答案自评。')}</p><p class="ch-progress-note">${partial(m)?'本组目前只有部分题目完成文字录入，剩余任务按原页作答。':'本组正在逐题整理，目前保留原书阅读与作答入口。'}</p>${pages(m)}<label class="ch-answer-label" for="ch-open-answer">按题号记录你的答案</label><textarea id="ch-open-answer" rows="8" data-ch-input="response" ${r?.groupSubmitted?'readonly':''}>${esc(value)}</textarea>${r?.groupSubmitted?`${m.answerNote?`<p class="ch-answer-note">${esc(m.answerNote)}</p>`:''}${pages(m,true)}<p class="ch-self-disclaimer">系统没有自动批改，请对照后记录自评。</p><div class="ch-actions"><button class="ch-primary" data-ch-action="self-mission" data-choice="mastered">已对照，符合要求</button><button class="ch-secondary" data-ch-action="self-mission" data-choice="review">还需复习</button></div>`:`<button class="ch-primary" data-ch-action="submit-open" ${!value.trim()?'disabled':''}>提交并查看参考 →</button>`}</article>`}
  function missingNote(m){return m.missingTasks?.length?`<aside class="ch-missing-material"><strong>当前资料尚缺以下附件</strong><ul>${m.missingTasks.map(t=>`<li>${esc(t.title)}：${esc(t.reason)}</li>`).join('')}</ul><p>已提供的题目可以照常练习；缺失部分没有被补写或算作已完成。</p></aside>`:''}
  function resultView(m){const r=result(m)||fresh(m),first=Object.values(r.firstAttempts||{}).filter(x=>x.kind==='auto');return `<section class="ch-panel ch-completion" id="ch-mission-result"><span class="ch-result-symbol">${r.reviewNeed?'↻':'✓'}</span><span class="ch-kicker">${esc(m.title)}</span><h1 id="ch-view-title" tabindex="-1">${incomplete(m)?'已完成可作答的部分。':'这一组，练完了。'}</h1><p>${r.reviewNeed?'把还不熟悉的地方留给下一轮。':'休息一下，再向前走一步。'}</p>${missingNote(m)}<div class="ch-summary-stats">${r.automaticTotal?`<div><strong>${r.automaticScore} / ${r.automaticTotal}</strong><span>本轮客观题答对</span></div>`:''}${first.length?`<div><strong>${first.filter(x=>x.correct).length} / ${first.length}</strong><span>首次作答答对</span></div>`:''}${r.selfTotal?`<div><strong>${r.selfScore} / ${r.selfTotal}</strong><span>自评符合要求</span></div>`:''}</div><p class="ch-progress-note">完成代表已作答并核对。看过答案后的改正与首次独立答对分开记录。</p><div class="ch-actions"><button class="ch-primary" data-ch-action="next-mission">${mi<missions.length-1?'下一组练习':'返回章节总览'} →</button><button class="ch-secondary" data-ch-action="retry">重新练习本组</button></div><button class="ch-text-link" data-ch-action="review-toggle">${r.manualReview?'取消手动复习标记':'另存为复习重点'}</button><details class="ch-answer-note"><summary>本组参考资料</summary>${m.answerNote?`<p>${esc(m.answerNote)}</p>`:''}${link(c?.answerPdf,'查看配套答案 PDF')}</details></section>`}
  function draw(){if(destroyed)return;const m=missions[mi];host.innerHTML=`<div class="ch-console ${view==='overview'?'':'ch-focused'}">${header()}${view==='learn'?learnView():view==='learn-done'?learnedSummary():view==='practice'&&m?itemView(m):view==='group'&&m?groupView(m):view==='result'&&m?resultView(m):overview()}</div>`}
  function checkItem(){const m=missions[mi],q=qs(m)[ii],k=keyOf(q,ii),value=s.drafts[dk(m,k)]||'',r=ensure(m);if(q.blocked||!hasAnswer(q,value)||r.checked[k]?.submitted)return;const a=auto(q),v={kind:a?'auto':'self',response:value,submitted:true,reviewed:a,correct:a?matches(value,q):null};if(!r.firstAttempts[k])r.firstAttempts[k]={correct:v.correct,kind:v.kind};if(v.correct)r.pendingReviewIds=r.pendingReviewIds.filter(x=>x!==k);r.checked[k]=v;aggregate(m);save(true);draw();host.querySelector('.ch-item-feedback')?.scrollIntoView?.({block:'nearest'})}
  function selfItem(choice){const m=missions[mi],q=qs(m)[ii],v=ensure(m).checked[keyOf(q,ii)];if(!v?.submitted||auto(q))return;v.correct=choice==='mastered';v.reviewed=true;if(v.correct){const r=ensure(m);r.pendingReviewIds=r.pendingReviewIds.filter(k=>k!==keyOf(q,ii))}aggregate(m);save(true);draw()}
  function nextItem(){const m=missions[mi],items=qs(m);if(!items[ii].blocked&&!checked(m,items[ii],ii)?.reviewed)return;if(ii<items.length-1){move('practice',{itemIndex:ii+1});return}const n=items.findIndex((q,i)=>!q.blocked&&!checked(m,q,i)?.reviewed);if(n>=0)move('practice',{itemIndex:n});else move(partial(m)&&!result(m)?.groupAssessed?'group':'result')}
  function editItem(){const m=missions[mi],r=ensure(m),key=keyOf(qs(m)[ii],ii);if(r.checked[key]?.correct===false&&!r.pendingReviewIds.includes(key))r.pendingReviewIds.push(key);delete r.checked[key];if(partial(m)){r.groupSubmitted=false;r.groupAssessed=false}aggregate(m,false);save();draw()}
  function retry(){const m=missions[mi],old=ensure(m),next=fresh(m);next.attempt=(old.attempt||1)+1;next.firstAttempts=old.firstAttempts;next.manualReview=Boolean(old.manualReview);next.pendingReviewIds=[...new Set([...(old.pendingReviewIds||[]),...Object.entries(old.checked).filter(([,v])=>v.correct===false).map(([k])=>k)])];next.pendingGroupReview=Boolean(old.pendingGroupReview||old.groupAssessed&&!old.groupCorrect);next.reviewNeed=next.pendingReviewIds.length>0||next.pendingGroupReview||next.manualReview;next.legacySummary=old.legacySummary||null;next.contentVersion=old.contentVersion||2;s.results[mk(m)]=next;qs(m).forEach((q,i)=>s.drafts[dk(m,keyOf(q,i))]='');s.drafts[dk(m,'response')]='';move(qs(m).length?'practice':'group');save()}
  function learnNext(){const r=rules[step];if(learnPane<paneCount(r)-1){move('learn',{step,learnPane:learnPane+1});return}if(r.check&&!s.results[ck()]?.submitted)return;award(`learn:${id}:${step}`);s.read[id]=rules.length>0&&rules.every((_,i)=>read(i));save(true);move(step<rules.length-1?'learn':'learn-done',{step:step+1})}
  function checkLearning(){const q=rules[step].check,k=ck(),response=s.drafts[k],old=s.results[k];if(!q||!response||old?.submitted)return;const correct=matches(response,q);s.results[k]={score:correct?1:0,total:1,submitted:true,response,firstCorrect:old?.firstCorrect??correct,attempts:(old?.attempts||0)+1};save(true);draw()}
  function reviewIndex(m){return Math.max(0,qs(m).findIndex((q,i)=>checked(m,q,i)?.correct===false||result(m)?.pendingReviewIds?.includes(keyOf(q,i))))}
  function review(){const n=missions.findIndex(m=>result(m)?.reviewNeed);if(n<0)return;const m=missions[n];move(qs(m).length?'practice':'group',{missionIndex:n,itemIndex:reviewIndex(m)})}
  function click(e){const b=e.target.closest?.('[data-ch-action]');if(!b||!host.contains(b)||b.disabled)return;const m=missions[mi];switch(b.dataset.chAction){
   case'back':destroy();opts.onBack?.();break;case'overview':move('overview');break;case'learn-tab':learn();break;case'practice-tab':practice();break;case'learn-step':move('learn',{step:+b.dataset.index});break;case'previous-step':if(learnPane>0)move('learn',{step,learnPane:learnPane-1});else move('learn',{step:step-1,learnPane:paneCount(rules[step-1])-1});break;case'learn-next':learnNext();break;case'check-learning':checkLearning();break;
   case'retry-check':{if(s.results[ck()])s.results[ck()].submitted=false;s.drafts[ck()]='';save();draw();break}
   case'mission':{const n=clamp(+b.dataset.index,missions.length);move(qs(missions[n]).length?'practice':'group',{missionIndex:n});break}
   case'check-item':checkItem();break;case'self-item':selfItem(b.dataset.choice);break;case'next-item':nextItem();break;case'previous-item':move('practice',{itemIndex:ii-1});break;case'edit-item':editItem();break;
   case'submit-open':{const r=ensure(m);if(!s.drafts[dk(m,'response')]?.trim()||(partial(m)&&!r.itemsSubmitted))return;r.groupSubmitted=true;aggregate(m,false);save(true);draw();break}
   case'self-mission':{const r=ensure(m);if(!r.groupSubmitted)return;r.groupAssessed=true;r.groupCorrect=b.dataset.choice==='mastered';if(r.groupCorrect)r.pendingGroupReview=false;aggregate(m);save(true);move('result');break}
   case'next-mission':if(mi+1<missions.length){const n=mi+1;move(qs(missions[n]).length?'practice':'group',{missionIndex:n})}else move('overview');break;
   case'retry':if(window.confirm('重新练习会清空本组当前草稿；首次答题记录、其他组进度和已有完成奖励会保留。继续吗？'))retry();break;
   case'review':review();break;case'review-toggle':{const r=ensure(m);r.manualReview=!r.manualReview;aggregate(m,false);save();draw();break}
  }}
  function input(e){const t=e.target,kind=t.dataset?.chInput;if(!kind)return;if(kind==='learn-check'){if(s.results[ck()]?.submitted)return;s.drafts[ck()]=t.value;const b=host.querySelector('[data-ch-action="check-learning"]');if(b)b.disabled=false;save();return}const m=missions[mi];if(!m)return;if(kind==='response'){if(result(m)?.groupSubmitted)return;s.drafts[dk(m,'response')]=t.value;const b=host.querySelector('[data-ch-action="submit-open"]');if(b)b.disabled=!t.value.trim()}else{const q=qs(m)[ii],k=keyOf(q,ii);if(checked(m,q,ii)?.submitted)return;const value=multi(q)?JSON.stringify([...host.querySelectorAll('[data-ch-input="option"]:checked')].map(i=>i.value)):t.value;s.drafts[dk(m,k)]=value;host.querySelectorAll('.ch-option').forEach(l=>l.classList.toggle('selected',Boolean(l.querySelector('input')?.checked)));const b=host.querySelector('[data-ch-action="check-item"]');if(b)b.disabled=!hasAnswer(q,value)}save()}
  function destroy(){if(destroyed)return;destroyed=true;abort.abort();instances.delete(host)}
  host.addEventListener('click',click,{signal:abort.signal});host.addEventListener('input',input,{signal:abort.signal});host.addEventListener('change',e=>{if(['option','learn-check'].includes(e.target.dataset?.chInput))input(e)},{signal:abort.signal});
  const api={destroy,showOverview:()=>move('overview'),showLearning:learn,showPractice:practice,showMission:index=>{const n=clamp(index,missions.length),m=missions[n];move(qs(m).length?'practice':'group',{missionIndex:n,itemIndex:reviewIndex(m)})}};instances.set(host,api);draw();return api;
 }
 window.StudyChapters={render};
})();
